      updated_at = pg_catalog.clock_timestamp();
  end loop;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'claim_started_at', claim_time,
    'claim_token', token, 'worker_id', worker,
    'runtime_generation_id', generation_id
